            aPrevious = aIngress;
            //
            aIngress = (RotL64(aEarthLaneA[((aIndex + 1981U)) & S_BLOCK1], 23U) ^ RotL64(aEarthLaneB[((aIndex + 3144U)) & S_BLOCK1], 5U));
            aIngress ^= RotL64(aFireLaneB[((aIndex + 4046U)) & S_BLOCK1], 48U);
