            aCross = (RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 4163U)) & S_BLOCK1], 37U) ^ RotL64(aEarthLaneD[((S_BLOCK1 - aIndex + 3243U)) & S_BLOCK1], 27U));
            aCross ^= RotL64(pSnowLaneD[((aIndex + 1350U)) & S_BLOCK1], 58U);
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aCross, 57U) + RotL64(aPrevious, 20U)) + (RotL64(aCarry, 5U) ^ RotL64(aIngress, 43U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterF = (aWandererH + RotL64(aCross, 60U)) + 0x28689DB7B315EB49ULL;
            aOrbiterD = (((aWandererC + RotL64(aIngress, 35U)) + RotL64(aCarry, 13U)) + 0x47288DDD82631B13ULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterJ = ((aWandererF + RotL64(aScatter, 11U)) + 0xC727BE9CE57C380FULL) + aTwistOrbiterAssignSaltD[((aIndex + 9U)) & S_SALT1];
            aOrbiterC = ((aWandererD + RotL64(aPrevious, 23U)) + RotL64(aCarry, 29U)) + 0x4875D2483ED0BDA6ULL;
            aOrbiterG = (aWandererA + RotL64(aIngress, 5U)) + 0x776EDE8B9D6C24B9ULL;
            aOrbiterB = ((aWandererG + RotL64(aCross, 53U)) + RotL64(aCarry, 53U)) + 0x2C19D2B7CE25B683ULL;
            aOrbiterA = (aWandererJ + RotL64(aScatter, 29U)) + 0x5413F67BE44640A6ULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x6E332D29E906C4EBULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterF) ^ 0x906BB9917D9B8B99ULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 6U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xCA8540B02C680F63ULL), 43U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0xBF1CEEB9D7B2095AULL;
