            aOrbiterF = RotL64((aOrbiterF * 0x88A7ECC5C7D8BDD7ULL), 23U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0x6CAF9EBA7E093928ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterJ) ^ 0x0A9EE045C3A91BCDULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 7U)) & S_SALT1];
