            aOrbiterB = RotL64((aOrbiterB * 0x73292D609AEA7777ULL), 51U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0x664CBAC12B1EFD15ULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0xE7B57B27A31A6AF3ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x86CFA9195D915F43ULL), 35U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterG) + 0xE40BDA6E2CA3E05DULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0xCE970691FA8CAD29ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x903E190AAF36432BULL), 13U);
            //
