            aIngress = aIngress + (RotL64(aOrbiterJ, 5U) ^ aOrbiterA);
            aIngress = aIngress + RotL64(aOrbiterF, 47U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererA = aWandererA + (((RotL64(aPrevious, 21U) + RotL64(aOrbiterJ, 11U)) + aOrbiterC) + RotL64(aCarry, 39U));
            aWandererC = aWandererC ^ (((RotL64(aIngress, 51U) + aOrbiterF) + RotL64(aOrbiterB, 27U)) + aTwistWandererUpdateSaltA[(((31U - aIndex) + 12U)) & S_SALT1]);
            aWandererF = aWandererF + ((RotL64(aCross, 35U) + aOrbiterG) + RotL64(aOrbiterJ, 35U));
            aWandererH = aWandererH ^ ((RotL64(aScatter, 42U) + RotL64(aOrbiterB, 20U)) + aOrbiterA);
            aWandererG = aWandererG + (((RotL64(aIngress, 11U) + RotL64(aOrbiterF, 51U)) + aOrbiterJ) + RotL64(aCarry, 53U));
            aWandererJ = aWandererJ ^ (((RotL64(aScatter, 5U) + RotL64(aOrbiterF, 5U)) + aOrbiterD) + aTwistWandererUpdateSaltB[(((31U - aIndex) + 11U)) & S_SALT1]);
            aWandererD = aWandererD + ((RotL64(aCross, 57U) + RotL64(aOrbiterD, 41U)) + aOrbiterC);
            //
