            //
            aIngress = (RotL64(aFireLaneC[((aIndex + 7961U)) & S_BLOCK1], 11U) ^ RotL64(aEarthLaneC[((aIndex + 7478U)) & S_BLOCK1], 34U));
            aIngress ^= RotL64(aFireLaneA[((aIndex + 8704U)) & S_BLOCK1], 47U);
            aIngress = TwistMix64::DiffuseC(aIngress);
            //
            aCross = (RotL64(aEarthLaneA[((S_BLOCK1 - aIndex + 9506U)) & S_BLOCK1], 4U) ^ RotL64(aEarthLaneD[((S_BLOCK1 - aIndex + 6781U)) & S_BLOCK1], 47U));
            aCross ^= RotL64(aKeyRowReadA[(((2047U - aIndex) + 8844U)) & W_KEY1], 19U);
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aPrevious, 23U) + RotL64(aCross, 57U)) + (RotL64(aIngress, 43U) ^ RotL64(aCarry, 6U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterK = (aWandererJ + RotL64(aScatter, 19U)) + 0x535D36BD1122C224ULL;
            aOrbiterI = (aWandererG + RotL64(aPrevious, 60U)) + 0x07A8A0C212BAECCEULL;
            aOrbiterG = (((aWandererF + RotL64(aCross, 53U)) + RotL64(aCarry, 57U)) + 0x981ABE4A75581791ULL) + aTwistOrbiterAssignSaltA[((aIndex + 13U)) & S_SALT1];
            aOrbiterD = (aWandererD + RotL64(aIngress, 27U)) + 0xE615F7139CBEDA9CULL;
            aOrbiterJ = (aWandererC + RotL64(aCross, 39U)) + 0x66CB5AC4E7F6DEE2ULL;
            aOrbiterF = (((aWandererA + RotL64(aPrevious, 13U)) + RotL64(aCarry, 21U)) + 0x638899CEB9E7ECF7ULL) + aTwistOrbiterAssignSaltF[((aIndex + 15U)) & S_SALT1];
            aOrbiterA = ((aWandererK + RotL64(aIngress, 5U)) + RotL64(aCarry, 39U)) + 0xD58226A6C3E8C23CULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0xD6E02DED24EB8D31ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0x593D390BC8F3246CULL;
            aOrbiterG = RotL64((aOrbiterG * 0xF5ED6304660ACD79ULL), 21U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterJ) + 0xA35B235B751D102CULL) + aTwistOrbiterUpdateSaltD[((aIndex + 11U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0x2666920D77F10D87ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x312B9F5D9BA45C8FULL), 37U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0xA54EB0207E44BDE8ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0xEEAEF48308BB6A85ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x0562D979A3D89CADULL), 5U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0x988D714F1B78C2D4ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterG) ^ 0x1E5794965893AC2FULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xF410CF20385EA053ULL), 13U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterK) + 0xE0934DA2E59DA3D5ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 10U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0x7E3E5C76A27BEA10ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x115AED61E25695E3ULL), 29U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0xE9B4CC134C5CA2FDULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0xE86DF3C46619FDE8ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x057185AE096A2D4BULL), 53U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterD) + 0x81CBE5E3994EBD10ULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterA) ^ 0x4A64E9586B2F47F4ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 23U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xDE3E1ED3B4C5F903ULL), 47U);
            //
            aIngress = aOrbiterA ^ RotL64(aOrbiterK, 18U);
            aIngress = aIngress + (aOrbiterG ^ RotL64(aOrbiterF, 53U));
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterJ, 47U));
            aIngress = aIngress + RotL64(aOrbiterD, 3U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 11U) + aOrbiterI) + RotL64(aOrbiterA, 53U));
            aWandererA = aWandererA + (((RotL64(aPrevious, 4U) + aOrbiterF) + RotL64(aOrbiterD, 37U)) + RotL64(aCarry, 39U));
            aWandererG = aWandererG ^ ((RotL64(aScatter, 41U) + RotL64(aOrbiterK, 19U)) + aOrbiterI);
            aWandererC = aWandererC + (((RotL64(aCross, 21U) + aOrbiterD) + RotL64(aOrbiterI, 27U)) + RotL64(aCarry, 13U));
            aWandererD = aWandererD ^ ((RotL64(aIngress, 57U) + aOrbiterJ) + RotL64(aOrbiterG, 43U));
            aWandererF = aWandererF + (((RotL64(aScatter, 27U) + aOrbiterK) + RotL64(aOrbiterJ, 60U)) + aTwistWandererUpdateSaltD[((aIndex + 22U)) & S_SALT1]);
            aWandererK = aWandererK ^ (((RotL64(aPrevious, 47U) + aOrbiterA) + RotL64(aOrbiterJ, 13U)) + aTwistWandererUpdateSaltF[(((31U - aIndex) + 20U)) & S_SALT1]);
