            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x2BC1693B07C39D2CULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterK) ^ 0x49C7CA8515DB8A18ULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 21U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x2FB0EEB77DBD0D5DULL), 39U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0x6C931DB9E2655E3EULL;
