            aWandererH = aWandererH + ((((RotL64(aIngress, 11U) + aOrbiterH) + RotL64(aOrbiterB, 27U)) + RotL64(aCarry, 11U)) + aTwistWandererUpdateSaltE[(((31U - aIndex) + 13U)) & S_SALT1]);
            aWandererF = aWandererF ^ (((RotL64(aPrevious, 23U) + RotL64(aOrbiterF, 12U)) + aOrbiterK) + aTwistWandererUpdateSaltC[((aIndex + 4U)) & S_SALT1]);
            aWandererB = aWandererB + ((RotL64(aCross, 35U) + aOrbiterK) + RotL64(aOrbiterH, 57U));
