            //
            aOrbiterA = ((aWandererA + RotL64(aScatter, 21U)) + 0xAB038979955AC254ULL) + aTwistOrbiterAssignSaltE[((aIndex + 8U)) & S_SALT1];
            aOrbiterF = (((aWandererB + RotL64(aCross, 60U)) + RotL64(aCarry, 11U)) + 0x338837CFADA4B44FULL) + aTwistOrbiterAssignSaltB[((aIndex + 20U)) & S_SALT1];
            aOrbiterJ = (aWandererG + RotL64(aIngress, 43U)) + 0x6BE9B64389317DE8ULL;
