            aOrbiterK = ((aWandererH + RotL64(aScatter, 51U)) + RotL64(aCarry, 47U)) + 0x29A252D306552C59ULL;
            aOrbiterI = (aWandererF + RotL64(aIngress, 37U)) + 0x2CA462E53B506E35ULL;
