            aOrbiterA = (aOrbiterA + aOrbiterF) + 0x98636B6C6136170BULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterA) ^ 0x77AC8945B30ADB90ULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x9D6E8ED5D4375A87ULL), 47U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0xE374EC9973F12273ULL;
