            aIngress ^= (RotL64(aKeyRowReadA[((aIndex + 10334U)) & W_KEY1], 26U) ^ RotL64(pSnowLaneA[((aIndex + 13269U)) & S_BLOCK1], 5U));
            aIngress = TwistMix64::DiffuseC(aIngress);
