            aCross ^= (RotL64(aEarthLaneA[((S_BLOCK1 - aIndex + 14306U)) & S_BLOCK1], 27U) ^ RotL64(pSnowLaneC[((aIndex + 9555U)) & S_BLOCK1], 13U));
