            //
            aScatter = (RotL64(aCarry, 57U) ^ RotL64(aPrevious, 26U)) + (RotL64(aCross, 41U) ^ RotL64(aIngress, 13U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterD = ((aWandererF + RotL64(aScatter, 5U)) + RotL64(aCarry, 47U)) + 0x581D3F8E7712C185ULL;
            aOrbiterA = ((aWandererA + RotL64(aIngress, 41U)) + RotL64(aCarry, 3U)) + 0xEAF0539F54D130C5ULL;
            aOrbiterC = ((aWandererE + RotL64(aPrevious, 35U)) + 0xA729A8DCE8AF3416ULL) + aTwistOrbiterAssignSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterI = ((aWandererJ + RotL64(aCross, 50U)) + 0x9EC90A7C7AA0D41AULL) + aTwistOrbiterAssignSaltC[((aIndex + 27U)) & S_SALT1];
            aOrbiterJ = (aWandererK + RotL64(aIngress, 21U)) + 0xF686EDA552E4B6ADULL;
            aOrbiterE = (aWandererC + RotL64(aScatter, 57U)) + 0xF92703C30CB0A133ULL;
            aOrbiterG = ((aWandererD + RotL64(aPrevious, 11U)) + RotL64(aCarry, 19U)) + 0x131A3C3C971D18BBULL;
            //
            aOrbiterD = ((aOrbiterD + aOrbiterA) + 0xCB49824540973983ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 8U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x2ED71D8E4EDA5978ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xEF887CE9EE602B35ULL), 23U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x70749177068BC896ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterA) ^ 0x8CE373607C65E82DULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x1C8B34AA29B50DA3ULL), 57U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x5D096241744DF901ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x51B9CF63EA430279ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xCA551B0DCD545107ULL), 3U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterC) + 0x7B02B16B1CEC062AULL) + aTwistOrbiterUpdateSaltD[((aIndex + 19U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0xE793D740F744749EULL;
            aOrbiterE = RotL64((aOrbiterE * 0xF18AA2B92D161B59ULL), 11U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0xB74E034B1E8DDD08ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterC) ^ 0x6728FEC8F447891AULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x7EEC8D0E445F316FULL), 35U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x6CAE862689C2292EULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0x45A182845738220AULL;
            aOrbiterD = RotL64((aOrbiterD * 0x359C286287C45551ULL), 29U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0x3D8911AEFC72E786ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0x92DB303D8510EDFDULL;
