            //
            aOrbiterJ = ((aWandererK + RotL64(aScatter, 5U)) + 0x649826BF4E9CD6C3ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterF = (aWandererB + RotL64(aCross, 11U)) + 0x3764DBC967EC58CCULL;
            aOrbiterK = (((aWandererF + RotL64(aIngress, 47U)) + RotL64(aCarry, 27U)) + 0x848D0470B1985CF4ULL) + aTwistOrbiterAssignSaltD[((aIndex + 23U)) & S_SALT1];
            aOrbiterD = ((aWandererA + RotL64(aPrevious, 54U)) + RotL64(aCarry, 11U)) + 0xF95D55D13A685E89ULL;
            aOrbiterE = (aWandererC + RotL64(aIngress, 21U)) + 0xA931CF85093E8613ULL;
