            aOrbiterG = ((aWandererH + RotL64(aCross, 37U)) + RotL64(aCarry, 43U)) + 0x67393FB7A18949E5ULL;
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterF) + 0x62BA0C1C374514C3ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 13U)) & S_SALT1];
