            //
            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0x324E45F4E1A465B8ULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0xDC72AB1AB196DC5AULL;
