            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x7778CE1DC534110EULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0xF8910768E5FA20C5ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x63A0B4C23C88EFAFULL), 57U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterE) + 0xC3CE2CF4523E3D65ULL) + aTwistOrbiterUpdateSaltA[((aIndex + 27U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x87A9639FB8CB08A6ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xD70F053742B0652FULL), 35U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterG) + 0x7E370B6B44DBF022ULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterC) ^ 0x2BB173413A4EF265ULL;
