            aOrbiterA = (aWandererB + RotL64(aCross, 12U)) + 0x36085F157713C991ULL;
            aOrbiterJ = ((aWandererJ + RotL64(aIngress, 5U)) + RotL64(aCarry, 3U)) + 0x60D7C71C907C4E2CULL;
            aOrbiterF = ((aWandererC + RotL64(aScatter, 35U)) + RotL64(aCarry, 37U)) + 0x57471D177B21C64BULL;
