            aOrbiterJ = ((aWandererF + RotL64(aScatter, 41U)) + RotL64(aCarry, 5U)) + 0xAB629C5B5625118BULL;
            aOrbiterD = ((aWandererD + RotL64(aPrevious, 19U)) + RotL64(aCarry, 57U)) + 0x586DABEDEA091CE1ULL;
            aOrbiterK = ((aWandererK + RotL64(aCross, 53U)) + RotL64(aCarry, 27U)) + 0x1CA154AB935D67C9ULL;
            aOrbiterB = ((aWandererI + RotL64(aIngress, 12U)) + 0x9CEB1633C2E175FAULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterH = ((aWandererB + RotL64(aScatter, 3U)) + 0xEC4137F451743774ULL) + aTwistOrbiterAssignSaltF[((aIndex + 8U)) & S_SALT1];
