            aCross = (RotL64(aShadowLaneA[((S_BLOCK1 - aIndex + 17760U)) & S_BLOCK1], 13U) ^ RotL64(aPoisonLaneB[((S_BLOCK1 - aIndex + 20228U)) & S_BLOCK1], 35U));
