            //
            aScatter = (RotL64(aIngress, 53U) ^ RotL64(aCross, 21U)) ^ (RotL64(aCarry, 5U) + RotL64(aPrevious, 38U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterJ = ((aWandererF + RotL64(aPrevious, 41U)) + RotL64(aCarry, 57U)) + 0x6B8C765DD29E3281ULL;
            aOrbiterI = ((aWandererE + RotL64(aCross, 34U)) + RotL64(aCarry, 43U)) + 0x108101F6ED625733ULL;
            aOrbiterE = (aWandererK + RotL64(aIngress, 13U)) + 0x88C79312FCCFE4C4ULL;
            aOrbiterF = ((aWandererI + RotL64(aScatter, 3U)) + 0x1C3DF0222F214C82ULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterK = ((aWandererD + RotL64(aCross, 23U)) + 0x67EBEE055310361CULL) + aKeyRotateOrbiterAssignSaltC[((aIndex + 21U)) & S_SALT1];
            aOrbiterC = (aWandererJ + RotL64(aScatter, 47U)) + 0xBC68EE9E35E4E7E1ULL;
            aOrbiterG = ((aWandererB + RotL64(aIngress, 53U)) + RotL64(aCarry, 23U)) + 0x87E5B848B5A41192ULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0xEA3DA206A1B258CAULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0xB3CAD4B892DBA105ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x9A7221AA0664C569ULL), 57U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterE) + 0x3B8E507DF14164A5ULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterI) ^ 0xC353D5BFB756C730ULL) ^ aKeyRotateOrbiterUpdateSaltA[((aIndex + 18U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xB7D061ECE6E808FDULL), 43U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterC) + 0xA61C4B6F295666F7ULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 28U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterK) ^ 0x6F519FB3F6B6FB96ULL) ^ aKeyRotateOrbiterUpdateSaltB[((aIndex + 17U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xED2E4930E386C055ULL), 21U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0x84537E865D08BC9DULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0xCFEAFAA760F04D23ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xD73B7E6C7326B0CBULL), 11U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0x8B57048FA337E5A2ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0x99F0623F509BB9F2ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x71CF032FCBDAD4CBULL), 37U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0xDCB39556ADD20EC6ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0x460E9DE79E6F0BF8ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x2645BC395EBE92CBULL), 27U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0x17967B624BA074EBULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0x6C8F5EE3B191E582ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xB65364A5DF4B5A05ULL), 3U);
            //
            aIngress = aOrbiterF ^ RotL64(aOrbiterI, 13U);
            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterC, 27U));
            aIngress = aIngress + (RotL64(aOrbiterG, 21U) ^ aOrbiterJ);
            aIngress = aIngress + RotL64(aOrbiterK, 46U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererK = aWandererK ^ (((RotL64(aScatter, 57U) + RotL64(aOrbiterC, 57U)) + aOrbiterI) + aKeyRotateWandererUpdateSaltF[(((31U - aIndex) + 15U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aPrevious, 11U) + aOrbiterE) + RotL64(aOrbiterJ, 30U)) + RotL64(aCarry, 21U));
            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 41U) + aOrbiterF) + RotL64(aOrbiterG, 19U));
            aWandererF = aWandererF + (((RotL64(aCross, 35U) + RotL64(aOrbiterC, 5U)) + aOrbiterK) + aKeyRotateWandererUpdateSaltD[(((31U - aIndex) + 3U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aScatter, 23U) + RotL64(aOrbiterG, 43U)) + aOrbiterC);
            aWandererD = aWandererD + (((RotL64(aCross, 50U) + aOrbiterF) + RotL64(aOrbiterC, 13U)) + RotL64(aCarry, 43U));
            aWandererI = aWandererI ^ ((RotL64(aPrevious, 3U) + RotL64(aOrbiterC, 51U)) + aOrbiterJ);
