            aIngress = (RotL64(aShadowLaneC[((aIndex + 26145U)) & S_BLOCK1], 29U) ^ RotL64(aShadowLaneA[((aIndex + 29127U)) & S_BLOCK1], 21U));
            aIngress ^= (RotL64(aKeyRowReadB[((aIndex + 28409U)) & W_KEY1], 41U) ^ RotL64(aEarthLaneD[((aIndex + 26864U)) & S_BLOCK1], 4U));
