            aCross = (RotL64(aShadowLaneB[((S_BLOCK1 - aIndex + 31640U)) & S_BLOCK1], 60U) ^ RotL64(aLightningLaneB[((S_BLOCK1 - aIndex + 27002U)) & S_BLOCK1], 29U));
