            aScatter = (RotL64(aCarry, 10U) ^ RotL64(aPrevious, 23U)) + (RotL64(aIngress, 57U) + RotL64(aCross, 37U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterI = (((aWandererB + RotL64(aIngress, 10U)) + RotL64(aCarry, 3U)) + 0xDE741B0DBD7AA363ULL) + aKeyRotateOrbiterAssignSaltF[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterC = ((aWandererG + RotL64(aPrevious, 37U)) + 0x71E59673A02835ECULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterF = (aWandererA + RotL64(aCross, 51U)) + 0x79454694E359D4BBULL;
            aOrbiterK = (aWandererJ + RotL64(aScatter, 3U)) + 0x6C7E4B1D98D7B844ULL;
            aOrbiterE = ((aWandererF + RotL64(aCross, 27U)) + RotL64(aCarry, 19U)) + 0x41472E4152E94E74ULL;
            aOrbiterD = ((aWandererD + RotL64(aPrevious, 19U)) + RotL64(aCarry, 53U)) + 0x1909D5A39646C821ULL;
            aOrbiterH = (aWandererI + RotL64(aScatter, 43U)) + 0xAE2CDC84592CC58CULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0xC0F4542BF02E866FULL;
