            aOrbiterK = (aOrbiterK + aOrbiterE) + 0x8F3AA4FA8A3C3EFDULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0x36519C8B1F35D18AULL;
            aOrbiterD = RotL64((aOrbiterD * 0x0BB1F0AF55F1220FULL), 3U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x6176443737A7929AULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterF) ^ 0x2A1E731876FA3FA2ULL) ^ aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x4B39620947C7E815ULL), 41U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0xBD3277B37152274FULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterE) ^ 0x0F2C4166580D0913ULL) ^ aKeyRotateOrbiterUpdateSaltE[((aIndex + 22U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xC343D8AB55549455ULL), 47U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0xB50FDCE8F083E244ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0xC2D7C9BD3B2E083BULL;
            aOrbiterI = RotL64((aOrbiterI * 0xAB24059BB57AF92FULL), 13U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0xE167D2039AD40578ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0xB5A45125AFA53A51ULL;
