            //
            aOrbiterH = ((aOrbiterH + aOrbiterI) + 0xC2C7C1B9DF79F2DCULL) + aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x72093D69F934E879ULL;
