            aWandererB = aWandererB ^ (((RotL64(aPrevious, 13U) + RotL64(aOrbiterE, 53U)) + aOrbiterF) + aKeyRotateWandererUpdateSaltB[((aIndex + 15U)) & S_SALT1]);
            aWandererJ = aWandererJ + ((RotL64(aIngress, 29U) + aOrbiterH) + RotL64(aOrbiterD, 13U));
