            aWandererA = aWandererA ^ ((RotL64(aScatter, 3U) + RotL64(aOrbiterE, 39U)) + aOrbiterA);
            aWandererJ = aWandererJ + (((RotL64(aIngress, 53U) + RotL64(aOrbiterH, 43U)) + aOrbiterF) + RotL64(aCarry, 27U));
            aWandererF = aWandererF ^ (((RotL64(aCross, 34U) + RotL64(aOrbiterB, 51U)) + aOrbiterG) + aKeyRotateWandererUpdateSaltC[((aIndex + 3U)) & S_SALT1]);
            aWandererD = aWandererD + ((RotL64(aPrevious, 11U) + aOrbiterE) + RotL64(aOrbiterH, 12U));
            aWandererC = aWandererC ^ (((RotL64(aCross, 43U) + RotL64(aOrbiterB, 57U)) + aOrbiterE) + aKeyRotateWandererUpdateSaltE[(((31U - aIndex) + 4U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererE, 3U) ^ aWandererA);
