            aOrbiterE = ((aWandererD + RotL64(aIngress, 3U)) + 0x75DDA499ECCE5184ULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterC = (((aWandererJ + RotL64(aPrevious, 39U)) + RotL64(aCarry, 35U)) + 0xA5335751660D31ABULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterD = (aWandererK + RotL64(aCross, 53U)) + 0x39CD0F36CD48CBF3ULL;
            aOrbiterG = ((aWandererA + RotL64(aIngress, 43U)) + RotL64(aCarry, 53U)) + 0x1DCF8A17C6056BC5ULL;
            aOrbiterK = (aWandererF + RotL64(aScatter, 13U)) + 0xAEC0474AC18165F4ULL;
            aOrbiterF = (aWandererG + RotL64(aPrevious, 18U)) + 0x8E44C343EF22D1F3ULL;
