            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x220FDE8642BE389FULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterD) ^ 0xDAAADAD1F645B488ULL) ^ aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x0D8F7BE7663E69B3ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0xD2DF80C6C821CB48ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0x9FCD472B054E0705ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x0B95E55E5A8E445DULL), 57U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0x2F5FA651E02109F8ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x79139DB0BB59C6B1ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x924748AB7CBB438DULL), 47U);
