            aOrbiterA = RotL64((aOrbiterA * 0xD108A78596F9193BULL), 21U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterF) + 0x8E4443FB54D20697ULL) + aKeyRotateOrbiterUpdateSaltF[((aIndex + 24U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterG) ^ 0x49B856981ECD076DULL) ^ aKeyRotateOrbiterUpdateSaltB[((aIndex + 16U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x28B5457B2C7BA56DULL), 11U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterC) + 0x0CFA5178EF4055F1ULL) + aKeyRotateOrbiterUpdateSaltA[((aIndex + 23U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0xE1C23C293FBE3BA6ULL;
