            aOrbiterG = (aWandererF + RotL64(aCross, 47U)) + 0xD6E2C1A452E437C2ULL;
            aOrbiterD = (aWandererE + RotL64(aScatter, 57U)) + 0x05859E7104953155ULL;
            aOrbiterJ = ((aWandererH + RotL64(aPrevious, 27U)) + RotL64(aCarry, 53U)) + 0xE6DB21A75DBB34E4ULL;
