            aOrbiterH = (aWandererC + RotL64(aPrevious, 21U)) + 0x790FA1DA1BD28DA5ULL;
            aOrbiterF = ((aWandererB + RotL64(aScatter, 34U)) + 0xACFD2CC16BEA611CULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterI = (aWandererK + RotL64(aCross, 5U)) + 0x8120545478AF3BC3ULL;
            //
