            aWandererH = aWandererH ^ ((RotL64(aCross, 23U) + aOrbiterF) + RotL64(aOrbiterI, 43U));
            aWandererJ = aWandererJ + ((RotL64(aPrevious, 13U) + RotL64(aOrbiterB, 41U)) + aOrbiterD);
