            aWandererF = aWandererF + ((RotL64(aCross, 3U) + aOrbiterH) + RotL64(aOrbiterD, 27U));
            aWandererK = aWandererK ^ (((RotL64(aIngress, 58U) + aOrbiterE) + RotL64(aOrbiterF, 52U)) + aKeyRotateWandererUpdateSaltC[(((31U - aIndex) + 21U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererB ^ RotL64(aWandererG, 36U));
