            aOrbiterA = RotL64((aOrbiterA * 0xA9D574B4BAF8A213ULL), 35U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0x5950C8989A876551ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterJ) ^ 0x827C43653F4D7788ULL) ^ aKeyRotateOrbiterUpdateSaltB[((aIndex + 4U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xC1523A0F8E52B3ADULL), 23U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x8F048517A4D46F0DULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0xF65BE389147856E1ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x184AB7428215CA27ULL), 57U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x59BE58509D12DA24ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0xD251E20DA3F3C4A6ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x22A738250DE665BBULL), 3U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterG) + 0x78F31E3E1F53F9FAULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0xCF302B50BF31B8BAULL;
            aOrbiterF = RotL64((aOrbiterF * 0x9F108B10D1E81EABULL), 53U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0xA8B55F6EF2892DD8ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x77495FA38C069465ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xA817EFA4C49F92F3ULL), 11U);
