            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x7EEAD5FBC20C1303ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0xEA049A097A8C58F7ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xBCD9446CFA6B78ADULL), 27U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0xA5B5DE412A927754ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0x83590BEBA7AE7935ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x7762A0E761F6E54BULL), 37U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0x586589D58C79B720ULL) + aKeyRotateOrbiterUpdateSaltF[((aIndex + 18U)) & S_SALT1];
