            //
            aCross = (RotL64(aVaporLaneC[((S_BLOCK1 - aIndex + 5425U)) & S_BLOCK1], 14U) ^ RotL64(aKeyRowReadB[(((2047U - aIndex) + 2182U)) & W_KEY1], 51U));
            aCross ^= (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 3352U)) & S_BLOCK1], 37U) ^ RotL64(aPoisonLaneD[((aIndex + 185U)) & S_BLOCK1], 23U));
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aPrevious, 5U) ^ RotL64(aCross, 53U)) + (RotL64(aCarry, 21U) + RotL64(aIngress, 40U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterI = ((aWandererH + RotL64(aCross, 29U)) + RotL64(aCarry, 57U)) + 0x732250E23E9EEB56ULL;
            aOrbiterG = (aWandererC + RotL64(aScatter, 48U)) + 0x75063E38BF1C090CULL;
            aOrbiterH = (((aWandererA + RotL64(aPrevious, 57U)) + RotL64(aCarry, 19U)) + 0x0F199EEA1A069DD4ULL) + aKeyRotateOrbiterAssignSaltE[((aIndex + 10U)) & S_SALT1];
            aOrbiterA = (aWandererD + RotL64(aIngress, 5U)) + 0x68FA7AF25AE21EB9ULL;
            aOrbiterK = (((aWandererE + RotL64(aScatter, 39U)) + RotL64(aCarry, 35U)) + 0x2B4E9BB0C11B929EULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterC = (aWandererK + RotL64(aPrevious, 23U)) + 0x66D7E3C9B0AED959ULL;
