            //
            aOrbiterI = ((aOrbiterI + aOrbiterG) + 0x304078792FA11231ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 19U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x0EA51D13CE5B56B6ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x7A340D6A4AC35879ULL), 47U);
