            aOrbiterC = ((aOrbiterC + aOrbiterH) + 0xB1110E74B18318A1ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 6U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0x021E97DC65F3F68EULL;
