            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0xF428AE4FC8E2AF1DULL;
            aOrbiterC = RotL64((aOrbiterC * 0x8B218FC736671963ULL), 35U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterC) + 0x7CC92566303E8809ULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterK) ^ 0xF388BACD5ACF2B1EULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 18U)) & S_SALT1];
