            aOrbiterG = ((aOrbiterG + aOrbiterJ) + 0x1CE05EA3A61615CBULL) + aKeySpawnOrbiterUpdateSaltD[((aIndex + 7U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0xC63529E77D9DB858ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x649AC71F69DD37C1ULL), 35U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterK) + 0x14E840E46DD7254FULL) + aKeySpawnOrbiterUpdateSaltA[((aIndex + 9U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0xCA91081F57F3F198ULL;
