            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0xB38EF3ECCD454A25ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xB421C161E9294073ULL), 47U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0x76AE5AD6A40FAF17ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0x74D40E352C2E47A1ULL;
